package edu.pe.cibertec.saibm.inventario.infrastructure.in.rest; import java.time.Instant; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; @RestController @RequestMapping("/api/v1/inventory/{bookId}") public class InventoryController {private final InventoryUseCase use;private final TransitionalWriteAuthorizer auth;public InventoryController(InventoryUseCase u,TransitionalWriteAuthorizer a){use=u;auth=a;}@PostMapping("/hold") public InventoryUseCase.View hold(@PathVariable String bookId,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,@Valid @RequestBody Request r,HttpServletRequest h){auth.require(h);require(key);return use.hold(bookId,r.quantity(),r.expiresAt(),key,c).view();}@PostMapping("/commit") public InventoryUseCase.View commit(@PathVariable String bookId,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);require(key);return use.commit(bookId,key,c).view();}@PostMapping("/release") public InventoryUseCase.View release(@PathVariable String bookId,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);require(key);return use.release(bookId,key,c).view();}private void require(String k){if(k==null||k.isBlank()||k.length()>200)throw new InvalidRequestException("Idempotency-Key is required");}public record Request(@Min(1)int quantity,@NotNull @Future Instant expiresAt){}}
